import{_ as a,o,c as t,a2 as i}from"./chunks/framework.DHmNT4rz.js";const u=JSON.parse('{"title":"i18n Guidelines","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"develop/i18n.md","filePath":"develop/i18n.md","lastUpdated":null}'),s={name:"develop/i18n.md"};function n(l,e,r,d,c,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This page mirrors <a href="https://github.com/mathias7799/SaaSWeave/blob/main/.agents/i18n.md" target="_blank" rel="noreferrer"><code>.agents/i18n.md</code></a> from the repository. Edit it at the source, not here.</p></div><h1 id="i18n-guidelines" tabindex="-1">i18n Guidelines <a class="header-anchor" href="#i18n-guidelines" aria-label="Permalink to &quot;i18n Guidelines&quot;">​</a></h1><h2 id="copy-keys" tabindex="-1">Copy Keys <a class="header-anchor" href="#copy-keys" aria-label="Permalink to &quot;Copy Keys&quot;">​</a></h2><p>Use the <code>{FEATURE_OR_PAGE}__{...MORE_SPECIFIC_IDENTIFIERS}</code> convention.</p><p>Examples:</p><ul><li><code>home_page__hero_title</code></li><li><code>auth__sign_in_title</code></li><li><code>navbar__dashboard</code></li></ul><h2 id="english-only-default" tabindex="-1">English-Only Default <a class="header-anchor" href="#english-only-default" aria-label="Permalink to &quot;English-Only Default&quot;">​</a></h2><p>Add new copy keys to <code>packages/i18n/messages/en.json</code> only by default. Do not edit <code>de.json</code> or any other non-English locale unless the user explicitly asks for translation work.</p><p>Translation is a separate agent workflow. Do not run machine translation or manually fill translated locale files as part of ordinary feature work.</p><h2 id="paraglide-codegen" tabindex="-1">Paraglide Codegen <a class="header-anchor" href="#paraglide-codegen" aria-label="Permalink to &quot;Paraglide Codegen&quot;">​</a></h2><p>If new or renamed keys need generated Paraglide modules for typecheck or runtime, run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @saasweave/i18n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>This is codegen, not translation.</p><h2 id="gotchas" tabindex="-1">Gotchas <a class="header-anchor" href="#gotchas" aria-label="Permalink to &quot;Gotchas&quot;">​</a></h2><ul><li>Do not call <code>m.*()</code> at module scope for labels, route config, nav config, or other long-lived objects. Store a function and resolve the translated string during render or request handling so SSR and hydration use the same locale.</li><li>For the current <code>{-$locale}</code> routing model, the URL is the source of truth: non-base locales use a path prefix and the base locale is unprefixed. Do not add cookie or preferred-language strategies ahead of <code>baseLocale</code>, because <code>/</code> must hydrate deterministically as the base locale.</li><li>Language switching should navigate to the localized URL through the TanStack Start i18n provider instead of calling Paraglide <code>setLocale()</code> directly from UI components.</li></ul>',15)])])}const g=a(s,[["render",n]]);export{u as __pageData,g as default};
